// === Tab: mySketch ===
// A RobRed Sketch

// Select your style: 'matrix', 'cyberBlue', or 'sinInTheCitadel'

// let currentStyle = "matrix";
// let currentStyle = 'cyberBlue';
let currentStyle = 'sinInTheCitadel';

let arcStretch = 1.5; // You might want to change this

let pQuan = [];
let pMlt = 7;
let pSize = 2;
let pDis = 11;
let pNum = 7;
let pOff = -1.2;
let pAlpha = 90;

let spin1 = 0.1;
let spin2 = 0.2;

const styles = {
  matrix: {
    bg: [5, 12, 6],
    glow: [0, 255, 70, 0.4],
    core: [180, 255, 200],
    nodes: [140, 255, 170, 240],
  },
  cyberBlue: {
    bg: [10, 10, 18],
    glow: [0, 195, 255, 0.4],
    core: [180, 240, 255],
    nodes: [220, 230, 255, 240],
  },
  sinInTheCitadel: {
    bg: [12, 3, 5],
    glow: [255, 0, 40, 0.45],
    core: [255, 200, 210],
    nodes: [255, 180, 0, 240],
  },
};

function setup() {
  createCanvas(windowWidth, windowHeight);
  for (let i = 0; i < pMlt; i++) {
    let pRot = (TWO_PI * i) / pMlt;
    let particles = new Particles(pSize, pDis, pNum, pRot);
    particles.initialise();
    pQuan.push(particles);
  }
}

function draw() {
  let activeTheme = styles[currentStyle];
  background(activeTheme.bg[0], activeTheme.bg[1], activeTheme.bg[2], pAlpha);
  translate(width / 2, height / 2);

  spin1 += 0.003;
  spin2 -= 0.005;

  let glitchChance = random();
  let strokeAlpha = map(sin(frameCount * 0.4), -1, 1, 40, 160);

  if (glitchChance > 0.96) strokeAlpha = random(180, 255);
  let allowDrawing = glitchChance >= 0.04;

  if (allowDrawing) {
    push();
    rotate(spin1);
    drawLatticeArcs(false, strokeAlpha, activeTheme);
    pop();

    push();
    rotate(spin2);
    drawLatticeArcs(true, strokeAlpha, activeTheme);
    pop();
  }

  noStroke();
  fill(
    activeTheme.nodes[0],
    activeTheme.nodes[1],
    activeTheme.nodes[2],
    activeTheme.nodes[3]
  );

  push();
  rotate(spin1);
  drawNodes(false);
  pop();

  push();
  rotate(spin2);
  drawNodes(true);
  pop();
}

function drawLatticeArcs(isInverse, baseAlpha, theme) {
  let scalar = isInverse ? pOff : 1.0;
  noFill();

  for (let a = 0; a < pQuan.length; a++) {
    let nextArm = (a + 1) % pQuan.length;
    let armA = pQuan[a];
    let armB = pQuan[nextArm];

    for (let i = 0; i < pNum; i++) {
      let x1 = armA.xPos[i] * scalar;
      let y1 = armA.yPos[i] * scalar;
      let x2 = armB.xPos[i] * scalar;
      let y2 = armB.yPos[i] * scalar;
      let ctrlX = ((x1 + x2) / 2) * arcStretch;
      let ctrlY = ((y1 + y2) / 2) * arcStretch;

      stroke(
        theme.glow[0],
        theme.glow[1],
        theme.glow[2],
        baseAlpha * theme.glow[3]
      );
      strokeWeight(4.5);
      bezier(x1, y1, ctrlX, ctrlY, ctrlX, ctrlY, x2, y2);
      stroke(theme.core[0], theme.core[1], theme.core[2], baseAlpha);
      strokeWeight(1.2);
      bezier(x1, y1, ctrlX, ctrlY, ctrlX, ctrlY, x2, y2);

      if (i < pNum - 1) {
        let x2Next = armB.xPos[i + 1] * scalar;
        let y2Next = armB.yPos[i + 1] * scalar;
        let ctrlXNext = ((x1 + x2Next) / 2) * arcStretch;
        let ctrlYNext = ((y1 + y2Next) / 2) * arcStretch;

        stroke(
          theme.glow[0],
          theme.glow[1],
          theme.glow[2],
          baseAlpha * theme.glow[3]
        );
        strokeWeight(4.5);
        bezier(
          x1,
          y1,
          ctrlXNext,
          ctrlYNext,
          ctrlXNext,
          ctrlYNext,
          x2Next,
          y2Next
        );
        stroke(theme.core[0], theme.core[1], theme.core[2], baseAlpha);
        strokeWeight(1.2);
        bezier(
          x1,
          y1,
          ctrlXNext,
          ctrlYNext,
          ctrlXNext,
          ctrlYNext,
          x2Next,
          y2Next
        );
      }
    }
  }
}

function drawNodes(isInverse) {
  var scalar = isInverse ? pOff : 1.0;
  for (let i = 0; i < pQuan.length; i++) {
    let arm = pQuan[i];
    for (let j = 0; j < pNum; j++) {
      ellipse(arm.xPos[j] * scalar, arm.yPos[j] * scalar, arm.particleSize[j]);
    }
  }
}

class Particles {
  constructor(s, d, n, a) {
    this.baseSize = s;
    this.baseDist = d;
    this.num = n;
    this.angle = a;
    this.xPos = [];
    this.yPos = [];
    this.particleSize = [];
  }

  initialise() {
    let currentDist = this.baseDist;
    for (let i = 0; i < this.num; i++) {
      if (i !== 0) currentDist *= 1.618;
      let theta = (HALF_PI * (i + 1)) / this.num;
      let zeta = this.angle + theta;
      this.xPos[i] = currentDist * cos(zeta);
      this.yPos[i] = currentDist * sin(zeta);
      this.particleSize[i] = this.baseSize + (1.618 * i * 5) / 3;
    }
  }
}

